[CmdletBinding()]
param([Parameter(Position=0)][string]$InputPath,[double]$WarnCorrelation=0.25,[double]$CriticalCorrelation=0,[double]$MinDurationMs=100,[double]$WindowMs=100,[double]$MinActiveDb=-70,[switch]$Json,[string]$Output,[switch]$Help)
. "$PSScriptRoot/lib/Common.ps1";. "$PSScriptRoot/lib/FFmpeg.ps1"
if($Help){'phasewatch BETA - timestamp stereo phase/correlation behavior';'Usage: .\phasewatch.ps1 INPUT [-WarnCorrelation X] [-CriticalCorrelation X] [-MinDurationMs MS] [-Json]';exit 0};if(-not $InputPath){[Console]::Error.WriteLine('input required');exit 2};Assert-CDLDependencies;if(-not(Test-Path -LiteralPath $InputPath -PathType Leaf)){[Console]::Error.WriteLine("unreadable input: $InputPath");exit 2};$p=(Resolve-Path -LiteralPath $InputPath).Path;$ch=Get-CDLProbeValue $p channels;if($ch -ne '2'){[Console]::Error.WriteLine('phasewatch requires exactly two decoded channels');exit 2}
$windows=@(Get-CDLPhaseSamples $p);$find=@();$prev=$null;foreach($r in $windows){if($r.correlation -lt $CriticalCorrelation){$find+=New-CDLFinding 'negative_correlation_segment' "correlation $($r.correlation) is below critical threshold $CriticalCorrelation"};if($null -ne $prev -and [math]::Abs($r.correlation-$prev)-gt .65){$find+=New-CDLFinding 'correlation_regime_change' "correlation changed sharply from $prev to $($r.correlation)"};$prev=$r.correlation}
$status=if($find.Count){'review'}else{'ok'};$report=[ordered]@{tool='phasewatch';version=$script:CDLVersion;generated_utc=[DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ');inputs=@($p);dependencies=Get-CDLVersions;options=[ordered]@{warn_correlation=$WarnCorrelation;critical_correlation=$CriticalCorrelation;min_duration_ms=$MinDurationMs;window_ms=$WindowMs;min_active_db=$MinActiveDb};measurements=[ordered]@{windows=$windows};findings=$find;status=$status};Write-CDLReport $report -Json:$Json -Output $Output -Text "phasewatch BETA: status=$status findings=$($find.Count)";if($find.Count){exit 1};exit 0
